  "agent": "The Commander",
  "agent_role": "decide",
  "situation": "The Commander is considering civilian medical support in an area where health infrastructure has been damaged or is non-existent. The decision concerns whether military assets are needed to meet a critical humanitarian need when no comparable civilian alternative is available. Civilian health providers and local authorities are relevant coordination partners. If PSF medical forces lead civilian provision, an appropriate civilian authority may later take over. The standard of support and the receiving nation's ability to sustain it are also relevant.",
  "question": "What should the Commander do about PSF medical support for civilians in an area with damaged or non-existent health infrastructure?",
  "facts": [
    {
      "id": "F1",
      "kind": "situation",
      "status": "confirmed",
      "fact": "The area under consideration has damaged or non-existent health infrastructure.",
      "spans": [
        "src:4dd8ce11148a#p91.4"
      ]
    },
    {
      "id": "F2",
      "kind": "authority",
      "status": "confirmed",
      "fact": "Military support should be requested only when no comparable civilian alternative exists and military or civil-defence assets can meet a critical humanitarian need.",
      "spans": [
        "src:4dd8ce11148a#p91.4"
      ]
    },
    {
      "id": "F3",
      "kind": "situation",
      "status": "confirmed",
      "fact": "Liaison with civilian health care providers is important for a coordinated and, where required, collaborative response.",
      "spans": [
        "src:4dd8ce11148a#p91.4"
      ]
    },
    {
      "id": "F4",
      "kind": "authority",
      "status": "confirmed",
      "fact": "Civilian medical support must be closely coordinated with local authorities or health care organizations and aligned with OCHA guidelines.",
      "spans": [
        "src:4dd8ce11148a#p91.4"
      ]
    },
    {
      "id": "F5",
      "kind": "authority",
      "status": "confirmed",
      "fact": "PSF medical forces should lead civilian health provision only when no civilian alternative is available and only until an appropriate civilian authority can take over.",
      "spans": [
        "src:4dd8ce11148a#p91.4"
      ]
    },
    {
      "id": "F6",
      "kind": "authority",
      "status": "confirmed",
      "fact": "Civilian medical support should be as close as possible to the receiving nation's peacetime standards and acceptable at least for the outcome to the providing nation.",
      "spans": [
        "src:4dd8ce11148a#p91.5"
      ]
    },
    {
      "id": "F7",
      "kind": "situation",
      "status": "confirmed",
      "fact": "The receiving nation must be able to sustain the provided standard over the long term.",
      "spans": [
        "src:4dd8ce11148a#p91.5"
      ]
    },
    {
      "id": "F8",
      "kind": "authority",
      "status": "confirmed",
      "fact": "Medical rules of eligibility define access to the military medical system by population category.",
